import csv, json
def to_json(path):
    with open(path, encoding='utf-8') as f:
        rows = [{'id': int(r['id']), 'sku': r['sku'].strip().upper(), 'price': float(r['price'])} for r in csv.DictReader(f)]
    return json.dumps({'total': len(rows), 'products': rows}, indent=2)
print(to_json('inv.csv'))
